mapper.select:
select hd.id as deviceId, hd.device_name as deviceName, hd.device_code as deviceCode, hd.device_type as deviceType, hd.area_id as areaId, hd.dept_id as deptId, (max(case when hdd.metric_code = 'electricity' then hdd.metric_value end) - min(case when hdd.metric_code = 'electricity' then hdd.metric_value end)) as kwh, avg(case when hdd.metric_code = 'power' then hdd.metric_value end) as avgPower, max(case when hdd.metric_code = 'power' then hdd.metric_value end) as maxPower, sum(case when hdd.metric_code = 'run_status' and (hdd.metric_value = 1 or hdd.metric_str in ('1')) then 1 else 0 end) as runPoints, sum(case when hdd.metric_code = 'run_status' and (hdd.metric_value = 0 or hdd.metric_str in ('0')) then 1 else 0 end) as standbyPoints, count(hdd.id) as totalPoints from hospital_device hd left join hospital_device_data hdd on hdd.device_id = hd.id and hdd.ts >= #{start} and hdd.ts <= #{end}
AND hd.id in
#{id}
group by hd.id, hd.device_name, hd.device_code, hd.device_type, hd.area_id, hd.dept_id

select d.day as day, sum(d.dayKwh) as kwh, avg(d.dayAvgPower) as avgPower from ( select date(hdd.ts) as day, hdd.device_id as deviceId, (max(case when hdd.metric_code = 'electricity' then hdd.metric_value end) - min(case when hdd.metric_code = 'electricity' then hdd.metric_value end)) as dayKwh, avg(case when hdd.metric_code = 'power' then hdd.metric_value end) as dayAvgPower from hospital_device_data hdd where hdd.ts >= #{start} and hdd.ts <= #{end}
AND hdd.device_id in
#{id}
group by date(hdd.ts), hdd.device_id ) d group by d.day order by d.day

select hour(hdd.ts) as hour, avg(hdd.metric_value) as avgPower from hospital_device_data hdd where hdd.metric_code = 'power' and hdd.metric_value is not null and hdd.ts >= #{start} and hdd.ts <= #{end}
AND hdd.device_id in
#{id}
group by hour(hdd.ts) order by hour(hdd.ts)
